    @MethodGridEntity(btnnameid = R.string.tv_external_pin_init, functionid = INDEX_EXTERNALPIN_INIT)
    private void initExternalPinpad() {
        extParams = new ExtParams();
        CommunicationTool.getInstance().init(context);
        String[] accessTypes = new String[]{"DEFAULT-USB","DOCK-UART","DOCK_USB1"};
        DialogUtils.createSingleChoiceDialog(context, context.getString(R.string.msg_select_access_type), accessTypes, new DialogUtils.SingleChoiceDialogCallback() {
            @Override
            public void onResult(int id) {
                if (id == 0) {
                    extParams.setAccessType(AccessType.DEFAULT_USB);
                    CommunicationTool.getInstance().setChannelType(ChannelType.DEFAULT_USB);
                    showMessage(R.string.msg_choose_default_usb, MessageTag.NORMAL);
                } else if (id == 1) {
                    extParams.setAccessType(AccessType.OTHERS);
                    CommunicationTool.getInstance().setChannelType(ChannelType.DOCK_UART);
                    showMessage(R.string.msg_choose_serial, MessageTag.NORMAL);
                } else if (id == 2) {
                    extParams.setAccessType(AccessType.OTHERS);
                    CommunicationTool.getInstance().setChannelType(ChannelType.DOCK_USB1);
                    showMessage(R.string.msg_choose_usb, MessageTag.NORMAL);
                }
                SDKExecutors.getFixedThreadPoolInstance().submit(()->{
                    boolean result = externalPinInput.init(CommunicationTool.getInstance().getCommunicationListener(),extParams);
                    if (result) {
                        showMessage(context.getString(R.string.msg_ext_pininput_init_pinpad_success) + "\r\n", MessageTag.NORMAL);
                    } else {
                        showMessage(context.getString(R.string.msg_ext_pininput_init_pinpad_exception) + "\r\n", MessageTag.ERROR);
                    }
                });
            }
        });

    }

    @MethodGridEntity(btnnameid = R.string.tv_load_mk, functionid = INDEX_EXTERNALPIN_LOAD_MK)
    private void externalPinpadLoadMk() {
        try {
            boolean result = false;
            String msg;
            showMessage(context.getString(R.string.msg_ext_pininput_start_load_main_key) + "\r\n", MessageTag.TIP);
            if (AppConfig.MKSK_SM4.equals(AppConfig.KEY_SYS_ALG)) {
                result = externalPinInput.loadMasterKey(LoadKeyMode.PLAIN, AlgorithmMode.SM4, indexMK,
                        ISOUtils.hex2byte(SM_MAINKEY), ISOUtils.hex2byte("F8D068"), null);
                msg = (result ? context.getString(R.string.msg_ext_pininput_load_SM4_main_key_success) :
                        context.getString(R.string.msg_ext_pininput_load_SM4_main_key_fail));
                showMessage(msg + "\r\n", MessageTag.DATA);
            } else if (AppConfig.MKSK_AES.equals(AppConfig.KEY_SYS_ALG)) {//AES默认KEK是16字节0x37
                //String mkAES = "B396917369B9B91711A0C9594B8D736E";//PLAIN KEY:11111111111111111111111111111111
                String mkAES = "11111111111111111111111111111111";
                result = externalPinInput.loadMasterKey(LoadKeyMode.PLAIN, AlgorithmMode.AES, indexMK,
                        ISOUtils.hex2byte(mkAES), ISOUtils.hex2byte("EE23D81C34"), null);
                msg = (result ? context.getString(R.string.msg_ext_pininput_load_main_key_success) :
                        context.getString(R.string.msg_ext_pininput_load_main_key_fail));
                showMessage(msg + "\r\n", MessageTag.DATA);
            } else {
                result = externalPinInput.loadMasterKey(LoadKeyMode.PLAIN, AlgorithmMode.DES, indexMK,
                        ISOUtils.hex2byte(MAINKEY), ISOUtils.hex2byte("82E136"), null);
                msg = (result ? context.getString(R.string.msg_ext_pininput_load_main_key_success) :
                        context.getString(R.string.msg_ext_pininput_load_main_key_fail));
                showMessage(msg + "\r\n", MessageTag.DATA);

                LoadMKExtParams loadMKExtParams = new LoadMKExtParams();
                loadMKExtParams.setKekIndex(AppConfig.Pin.MKSK_DES_INDEX_MK);
                result = externalPinInput.loadMasterKey(LoadKeyMode.CUSTOM_ENCRYPT, AlgorithmMode.DES, indexMK + 1,
                        ISOUtils.hex2byte(MAINKEY), ISOUtils.hex2byte("4CA89C"), loadMKExtParams);
                msg = (result ? context.getString(R.string.msg_ext_pininput_load_main_key_success) :
                        context.getString(R.string.msg_ext_pininput_load_main_key_fail));
                showMessage(msg + "\r\n", MessageTag.DATA);
            }
        } catch (Exception e) {
            showMessage(context.getString(R.string.msg_ext_pininput_load_main_key_excetption) + e + "\r\n",
                    MessageTag.NORMAL);
        }

    }

    @MethodGridEntity(btnnameid = R.string.tv_load_wk, functionid = INDEX_EXTERNALPIN_LOAD_WK)
    private void externalPinpadLoadWK() {
        try {
            boolean result = false;
            String msg;
            if (AppConfig.MKSK_DES.equals(AppConfig.KEY_SYS_ALG)) {
                result = externalPinInput.loadWorkingKey(WorkingKeyType.PIN, AlgorithmMode.DES, indexMK,
                        indexWKPin, ISOUtils.hex2byte(WORKINGKEY_DATA_PIN), ISOUtils.hex2byte("58A2BB"));

                msg = (result ? context.getString(R.string.msg_load_pin_wk_succ) :
                        context.getString(R.string.msg_load_pin_wk_failed));
                showMessage(msg + "\r\n", MessageTag.DATA);

                result = externalPinInput.loadWorkingKey(WorkingKeyType.MAC, AlgorithmMode.DES, indexMK,
                        indexWKMac, ISOUtils.hex2byte(WORKINGKEY_DATA_MAC), ISOUtils.hex2byte("94897B"));

                msg = (result ? context.getString(R.string.msg_load_mac_wk_succ) :
                        context.getString(R.string.msg_load_mac_wk_failed));
                showMessage(msg + "\r\n", MessageTag.DATA);

                result = externalPinInput.loadWorkingKey(WorkingKeyType.TRACK, AlgorithmMode.DES, indexMK,
                        indexWKTrack, ISOUtils.hex2byte(WORKINGKEY_DATA_TRACK), ISOUtils.hex2byte("5B4C8B"));

                msg = (result ? context.getString(R.string.msg_load_track_wk_succ) :
                        context.getString(R.string.msg_load_track_wk_failed));
                showMessage(msg + "\r\n", MessageTag.DATA);
            } else if (AppConfig.MKSK_SM4.equals(AppConfig.KEY_SYS_ALG)) {
                result = externalPinInput.loadWorkingKey(WorkingKeyType.PIN, AlgorithmMode.SM4, indexMK,
                        indexWKPin, ISOUtils.hex2byte(SM_WORKINGKEY_DATA_PIN), null);

                msg = (result ? context.getString(R.string.msg_load_pin_wk_succ) :
                        context.getString(R.string.msg_load_pin_wk_failed));
                showMessage(msg + "\r\n", MessageTag.DATA);

                result = externalPinInput.loadWorkingKey(WorkingKeyType.MAC, AlgorithmMode.SM4, indexMK,
                        indexWKMac, ISOUtils.hex2byte(SM_WORKINGKEY_DATA_MAC), null);

                msg = (result ? context.getString(R.string.msg_load_mac_wk_succ) :
                        context.getString(R.string.msg_load_mac_wk_failed));
                showMessage(msg + "\r\n", MessageTag.DATA);

                result = externalPinInput.loadWorkingKey(WorkingKeyType.TRACK, AlgorithmMode.SM4, indexMK,
                        indexWKTrack, ISOUtils.hex2byte(SM_WORKINGKEY_DATA_TRACK), null);

                msg = (result ? context.getString(R.string.msg_load_track_wk_succ) :
                        context.getString(R.string.msg_load_track_wk_failed));
                showMessage(msg + "\r\n", MessageTag.DATA);

            } else if (AppConfig.MKSK_AES.equals(AppConfig.KEY_SYS_ALG)) {
                byte[] pinKeyAES = ISOUtils.hex2byte("34A9575EEFE69DE078B4E29A24D04CD7");//PLAIN
                // KEY:66666666666666666666666666666666
                byte[] checkKcv = ISOUtils.hex2byte("2DB6A815C6");
                result = externalPinInput.loadWorkingKey(WorkingKeyType.PIN, AlgorithmMode.AES, indexMK, indexWKPin,
                        pinKeyAES, checkKcv);
                msg = (result ? context.getString(R.string.msg_load_pin_wk_succ) :
                        context.getString(R.string.msg_load_pin_wk_failed));
                showMessage(msg + "\r\n", MessageTag.DATA);

                byte[] macKeyAES = ISOUtils.hex2byte("DC44B424BCB85288CE3BE42430864E8B");//PLAIN
                // KEY:77777777777777777777777777777777
                byte[] macKcv = ISOUtils.hex2byte("2C3F18B2B6");//由密钥明文与全0 数据计算mac
                result = externalPinInput.loadWorkingKey(WorkingKeyType.MAC, AlgorithmMode.AES, indexMK, indexWKMac,
                        macKeyAES, macKcv);
                msg = (result ? context.getString(R.string.msg_load_mac_wk_succ) :
                        context.getString(R.string.msg_load_mac_wk_failed));
                showMessage(msg + "\r\n", MessageTag.DATA);

                byte[] trackKeyAES = ISOUtils.hex2byte("06C8D45B628EAEA8A30C75579F321211");//PLAIN
                // KEY:88888888888888888888888888888888
                byte[] trackKcv = ISOUtils.hex2byte("8B4217FEA6");
                result = externalPinInput.loadWorkingKey(WorkingKeyType.TRACK, AlgorithmMode.AES, indexMK,
                        indexWKTrack, trackKeyAES, trackKcv);
                msg = (result ? context.getString(R.string.msg_load_track_wk_succ) :
                        context.getString(R.string.msg_load_track_wk_failed));
                showMessage(msg + "\r\n", MessageTag.DATA);
            }
        } catch (Exception e) {
            e.printStackTrace();
            showMessage(context.getString(R.string.msg_ext_pininput_load_working_key_excetption) + e + "\r\n",
                    MessageTag.ERROR);
        }
    }

    @MethodGridEntity(btnnameid = R.string.tv_pin_cal_mac, functionid = INDEX_EXTERNALPIN_CAL_MAC)
    private void externalPinpadCalMac() {
        try {
            // String data =
            // "";

            showMessage(context.getString(R.string.msg_ext_pininput_start_calculate_mac) + "\r\n", MessageTag.TIP);
            MacResult calacMac = null;
            DialogUtils.createCustomDialog(context, context.getString(R.string.msg_cal_mac), null,
                    R.layout.dialog_caclmac, new DialogUtils.CustomDialogCallback() {
                        @Override
                        public void onResult(int id, View dialogView) {
                            try {
                                if (id == -1) {//cancel
                                    return;
                                }
                                KeyManagement keyManagement = KeyManagement.MKSK;
                                if (AppConfig.DUKPT_DES.equals(AppConfig.KEY_SYS_ALG)) {
                                    keyManagement = KeyManagement.DUKPT;
                                    indexWKMac = dukptIndex;
                                }
                                EditText value = (EditText) dialogView.findViewById(R.id.edit_caclmac_value);
                                String string = value.getText().toString();
                                byte[] input = string.getBytes("GBK");
                                int macAlgorithm = MacAlgorithm.DES.ECB;
                                RadioGroup group1 = dialogView.findViewById(R.id.radioGroup_mac_type);
                                if (R.id.radio_MAC_ECB == group1.getCheckedRadioButtonId()) {
                                    macAlgorithm = MacAlgorithm.DES.ECB;
                                } else if (R.id.radio_MAC_X99 == group1.getCheckedRadioButtonId()) {
                                    macAlgorithm = MacAlgorithm.DES.X99;
                                } else if (R.id.radio_MAC_X919 == group1.getCheckedRadioButtonId()) {
                                    macAlgorithm = MacAlgorithm.DES.X919;
                                } else if (R.id.radio_MAC_9606 == group1.getCheckedRadioButtonId()) {
                                    macAlgorithm = MacAlgorithm.DES.M9606;
                                } else if (R.id.radio_MAC_CBC == group1.getCheckedRadioButtonId()) {
                                    macAlgorithm = MacAlgorithm.DES.CBC;
                                } else if (R.id.radio_MAC_SM4 == group1.getCheckedRadioButtonId()) {
                                    macAlgorithm = MacAlgorithm.SM4.X99;
                                } else if (R.id.radio_MAC_AES == group1.getCheckedRadioButtonId()) {
                                    macAlgorithm = MacAlgorithm.AES.X99;
                                } else if (R.id.radio_MAC_SM4_union == group1.getCheckedRadioButtonId()) {
                                    macAlgorithm = MacAlgorithm.SM4.SM4_UNIONPAY;
                                }
                                byte[] output = externalPinInput.calcMac(keyManagement, macAlgorithm, indexWKMac, input,
                                        null).getMac();
                                showMessage(context.getString(R.string.msg_enter_value) + string + "\r\n", MessageTag.DATA);
                                showMessage(context.getString(R.string.msg_mac_algorithm) + macAlgorithm + "\r\n",
                                        MessageTag.DATA);
                                showMessage(context.getString(R.string.msg_mac_cal_result) + (output == null ? null :
                                        ISOUtils.hexString(output)), MessageTag.DATA);
                            } catch (SDKRTException e) {
                                showMessage(context.getString(R.string.msg_error) + e, MessageTag.ERROR);
                            } catch (UnsupportedEncodingException e) {
                                showMessage(context.getString(R.string.msg_enter_value_error) + "\r\n", MessageTag.ERROR);
                            } catch (Exception e) {
                                showMessage(e.getMessage(), MessageTag.ERROR);
                            }
                        }
                    });
        } catch (Exception e) {
            showMessage(context.getString(R.string.msg_ext_pininput_calculate_mac_exception) + e + "\r\n",
                    MessageTag.ERROR);
        }
    }

    @MethodGridEntity(btnnameid = R.string.tv_pin_encry, functionid = INDEX_EXTERNALPIN_ENCRY)
    private void externalPinpadEncry() {
        try {
            showMessage(context.getString(R.string.msg_ext_pininput_start_encrypt_data) + "\r\n", MessageTag.TIP);
            CipherResult encryptData = null;
            final String encry = "1234567812345678adcbadcbadcbadcb";
            //final String encry =
            // "";
            DialogUtils.createCustomDialog(context, R.string.common_encrypt, null, R.layout.dialog_encryption,
                    new DialogUtils.CustomDialogCallback2() {
                        @Override
                        public void onInit(View view) {
                            EditText value = view.findViewById(R.id.edit_encryption_value);
                            // value.setText("1234567812345678adcbadcbadcbadcb");
                            value.setText(encry);
                        }

                        @Override
                        public void onResult(int id, View dialogView) {
                            EditText value = (EditText) dialogView.findViewById(R.id.edit_encryption_value);
                            AlgorithmMode algorithmMode = AlgorithmMode.DES;
                            CipherMode cipherMode = CipherMode.ECB;
                            CipherExtParams cipherExtParams = new CipherExtParams();
                            try {
                                KeyManagement keyManagement = KeyManagement.MKSK;
                                byte[] input = ISOUtils.hex2byte(value.getText().toString());
                                RadioGroup group1 = dialogView.findViewById(R.id.radioGroup_encrypt_type1);
                                byte[] cbciv = null;
                                if (R.id.radio_CBC == group1.getCheckedRadioButtonId()) {
                                    cipherMode = CipherMode.CBC;
                                    if (AppConfig.MKSK_DES.equals(AppConfig.KEY_SYS_ALG) || AppConfig.DUKPT_DES.equals(AppConfig.KEY_SYS_ALG)) {
                                        cbciv = new byte[]{0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01};
                                    } else if (AppConfig.MKSK_SM4.equals(AppConfig.KEY_SYS_ALG) || AppConfig.MKSK_AES.equals(AppConfig.KEY_SYS_ALG)) {
                                        cbciv = new byte[]{0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01,
                                                0x01, 0x01, 0x01, 0x01, 0x01};
                                    }
                                } else if (R.id.radio_ECB == group1.getCheckedRadioButtonId()) {
                                    cipherMode = CipherMode.ECB;
                                }
                                if (AppConfig.MKSK_DES.equals(AppConfig.KEY_SYS_ALG)) {
                                    algorithmMode = AlgorithmMode.DES;
                                    indexWKTrack = AppConfig.Pin.MKSK_DES_INDEX_WK_TRACK;
                                } else if (AppConfig.MKSK_SM4.equals(AppConfig.KEY_SYS_ALG)) {
                                    algorithmMode = AlgorithmMode.SM4;
                                    indexWKTrack = AppConfig.Pin.MKSK_SM4_INDEX_WK_TRACK;
                                } else if (AppConfig.MKSK_AES.equals(AppConfig.KEY_SYS_ALG)) {
                                    algorithmMode = AlgorithmMode.AES;
                                    indexWKTrack = AppConfig.Pin.MKSK_AES_INDEX_WK_TRACK;
                                } else if (AppConfig.DUKPT_DES.equals(AppConfig.KEY_SYS_ALG)) {
                                    algorithmMode = AlgorithmMode.DES;
                                    keyManagement = KeyManagement.DUKPT;
                                    indexWKTrack = dukptIndex;
                                }
                                cipherExtParams.setCbcInit(cbciv);
                                CipherResult cipherResult = externalPinInput.encrypt(keyManagement, algorithmMode, cipherMode
                                        , indexWKTrack, input, cipherExtParams);

                                showMessage(context.getString(R.string.msg_encrypt_data) + value.getText().toString() + "\r\n"
                                        , MessageTag.DATA);
                                showMessage(context.getString(R.string.msg_encrypt_key) + AppConfig.KEY_SYS_ALG + "\r\n",
                                        MessageTag.DATA);
                                showMessage(context.getString(R.string.msg_encrypt_mode) + algorithmMode, MessageTag.DATA);
                                showMessage(context.getString(R.string.msg_encrypt_result) + (cipherResult.getData() == null
                                        ? null : ISOUtils.hexString(cipherResult.getData())) + "\r\n", MessageTag.DATA);
                                AppConfig.Pin.encryptResult = cipherResult.getData();
                            } catch (Exception e) {
                                e.printStackTrace();
                                showMessage(context.getString(R.string.msg_encrypt_ex) + e, MessageTag.ERROR);
                                showMessage(context.getString(R.string.msg_encrypt_data) + value.getText().toString(),
                                        MessageTag.ERROR);
                                showMessage(context.getString(R.string.msg_encrypt_key) + AppConfig.KEY_SYS_ALG,
                                        MessageTag.ERROR);
                                showMessage(context.getString(R.string.msg_encrypt_mode) + algorithmMode, MessageTag.ERROR);

                            }
                        }
                    });


        } catch (Exception e) {
            e.printStackTrace();
            showMessage(context.getString(R.string.msg_ext_pininput_encrypt_exception) + e + "\r\n", MessageTag.ERROR);
        }
    }

    @MethodGridEntity(btnnameid = R.string.tv_pin_decry, functionid = INDEX_EXTERNALPIN_DECRY)
    private void externalPinpadDecry() {
        try {
            CipherResult decryptData = null;
            DialogUtils.createCustomDialog(context, R.string.common_decrypt, null, R.layout.dialog_encryption,
                    new DialogUtils.CustomDialogCallback2() {
                        @Override
                        public void onInit(View view) {
                            EditText value = view.findViewById(R.id.edit_encryption_value);
                            if (AppConfig.Pin.encryptResult == null) {
                                value.setHint(context.getString(R.string.msg_enter_or_encrypt_first));
                            } else {
                                value.setText(ISOUtils.hexString(AppConfig.Pin.encryptResult));
                            }
                        }

                        @Override
                        public void onResult(int id, View dialogView) {
                            EditText value = (EditText) dialogView.findViewById(R.id.edit_encryption_value);
                            AlgorithmMode algorithmMode = AlgorithmMode.DES;
                            CipherMode cipherMode = CipherMode.ECB;
                            CipherExtParams cipherExtParams = new CipherExtParams();
                            KeyManagement keyManagement = KeyManagement.MKSK;
                            try {
                                byte[] input = ISOUtils.hex2byte(value.getText().toString());
                                RadioGroup group1 = dialogView.findViewById(R.id.radioGroup_encrypt_type1);
                                byte[] cbciv = null;
                                if (R.id.radio_CBC == group1.getCheckedRadioButtonId()) {
                                    cipherMode = CipherMode.CBC;
                                    if (AppConfig.MKSK_DES.equals(AppConfig.KEY_SYS_ALG) || AppConfig.DUKPT_DES.equals(AppConfig.KEY_SYS_ALG)) {
                                        cbciv = new byte[]{0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01};
                                    } else if (AppConfig.MKSK_SM4.equals(AppConfig.KEY_SYS_ALG) || AppConfig.MKSK_AES.equals(AppConfig.KEY_SYS_ALG)) {
                                        cbciv = new byte[]{0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01,
                                                0x01, 0x01, 0x01, 0x01, 0x01};
                                    }
                                } else if (R.id.radio_ECB == group1.getCheckedRadioButtonId()) {
                                    cipherMode = CipherMode.ECB;
                                }
                                if (AppConfig.MKSK_DES.equals(AppConfig.KEY_SYS_ALG)) {
                                    algorithmMode = AlgorithmMode.DES;
                                } else if (AppConfig.MKSK_SM4.equals(AppConfig.KEY_SYS_ALG)) {
                                    algorithmMode = AlgorithmMode.SM4;
                                } else if (AppConfig.MKSK_AES.equals(AppConfig.KEY_SYS_ALG)) {
                                    algorithmMode = AlgorithmMode.AES;
                                } else if (AppConfig.DUKPT_DES.equals(AppConfig.KEY_SYS_ALG)) {
                                    algorithmMode = AlgorithmMode.DES;
                                    keyManagement = KeyManagement.DUKPT;
                                    indexWKTrack = dukptIndex;
                                }
                                cipherExtParams.setCbcInit(cbciv);
                                CipherResult cipherResult = externalPinInput.decrypt(keyManagement, algorithmMode, cipherMode
                                        , indexWKTrack, input, cipherExtParams);

                                showMessage(context.getString(R.string.msg_decrypt_data) + value.getText().toString(),
                                        MessageTag.DATA);
                                showMessage(context.getString(R.string.msg_decrypt_key) + AppConfig.KEY_SYS_ALG,
                                        MessageTag.DATA);
                                showMessage(context.getString(R.string.msg_decrypt_mode) + algorithmMode, MessageTag.DATA);
                                showMessage(context.getString(R.string.msg_decrypt_result) + (cipherResult.getData() == null
                                        ? null : ISOUtils.hexString(cipherResult.getData())), MessageTag.DATA);
                                showMessage(context.getString(R.string.msg_check_hint), MessageTag.TIP);
                            } catch (Exception e) {
                                e.printStackTrace();
                                showMessage(context.getString(R.string.msg_decrypt_ex) + e.getMessage(), MessageTag.ERROR);
                                showMessage(context.getString(R.string.msg_decrypt_data) + value.getText().toString(),
                                        MessageTag.ERROR);
                                showMessage(context.getString(R.string.msg_decrypt_key) + AppConfig.KEY_SYS_ALG,
                                        MessageTag.ERROR);
                                showMessage(context.getString(R.string.msg_decrypt_mode) + algorithmMode, MessageTag.ERROR);
                            }
                        }
                    });
        } catch (Exception e) {
            showMessage(context.getString(R.string.msg_ext_pininput_decrypt_exception) + e + "\r\n", MessageTag.ERROR);
        }
    }

