    @MethodGridEntity(btnnameid = R.string.tv_external_sign, functionid = INDEX_EXTERNALPIN_SIGN)
    private void externalPinpadSign() {
        try {
            showMessage(context.getString(R.string.msg_ext_pininput_sign) + "\r\n", MessageTag.TIP);
            boolean result = signatureModule.init(null, extParams);
            if (!result) {
                showMessage(context.getString(R.string.msg_ext_pininput_init_failed), MessageTag.ERROR);
                return;
            }
            if (!signatureModule.handShake()) {
                showMessage("握手失败", MessageTag.ERROR);
                return;
            }
            SignatureExtParams params = new SignatureExtParams();
            params.setBordTimeout(10);
            params.setReSignTimes(5);
//            result = signatureModule.setSignatureParams();
            if (!result) {
                showMessage(context.getString(R.string.msg_ext_pininput_setparams_failed), MessageTag.ERROR);
                return;
            }
            byte[] data = signatureModule.doSign("1A2B3C4D", params);
            showMessage(context.getString(R.string.msg_ext_pininput_sign_result) + (data == null ? "null" :
                    ISOUtils.hexString(data)) + "\r\n", MessageTag.TIP);
            if (data != null) {
//                File file = new File("/sdcard/ddd.jpeg");
//                file.delete();
//                file.createNewFile();
//                FileOutputStream fos = new FileOutputStream(file);
                Bitmap bmp = BitmapFactory.decodeByteArray(data, 3, data.length - 3);
                if (null != bmp) {
                    showImage(bmp);
                }
//                    bmp.compress(Bitmap.CompressFormat.JPEG, 100, fos);
            }
            showMessage(context.getString(R.string.msg_ext_pininput_sign_end) + "\r\n", MessageTag.DATA);


        } catch (Exception e) {
            e.printStackTrace();
            showMessage(context.getString(R.string.msg_ext_pininput_sign_exception) + "\r\n", MessageTag.ERROR);
            showMessage(e.getMessage() + "\r\n", MessageTag.ERROR);
        }
    }

